fn mk_at<T>(f: impl for<'a> Fn(&'a mut m::Fit) -> Option<&'a mut T> + 'static) -> At<T> {
    Rc::new(f)
}
fn mk_see<T>(f: impl for<'a> Fn(&'a m::Fit) -> Option<&'a T> + 'static) -> See<T> {
    Rc::new(f)
}

fn preset_config(preset: u32) -> arael::simple_lm::LmConfig<f64> {
    match preset {
        1 => arael::simple_lm::LmConfig::conservative(),
        2 => arael::simple_lm::LmConfig::well_conditioned(),
        3 => arael::simple_lm::LmConfig::ill_conditioned(),
        _ => arael::simple_lm::LmConfig::default(),
    }
}

